import{_ as n,c as i,o as r,a2 as t}from"./chunks/framework.PGES7OoM.js";const h=JSON.parse('{"title":"Curvy for Enterprises & Institutions","description":"","frontmatter":{"rawMarkdown":"# Curvy for Enterprises & Institutions\\n\\n> [!NOTE]\\n> To get started with enterprise Curvy integration, [schedule a call with our CEO, Petar](https://curvy.box/petar).\\n\\n## Private payments, branded and controlled\\n\\nCurvy enables enterprises and institutions to deploy privacy-enabled payment infrastructure with full branding, compliance alignment, and operational control.\\n\\nBuilt for organizations that require privacy, regulatory alignment, full customization, and scalable execution.\\n\\n---\\n\\n## Enterprise capabilities\\n\\n### White-label user domains\\n\\nLaunch enterprise-branded programmable identities.\\n\\nExample:\\n\\n`satoshi.yourcompany.io`  \\ninstead of  \\n`satoshi.curvy.name`\\n\\nThis allows you to:\\n\\n- Own the identity layer\\n- Control user namespaces\\n- Align on-chain identity with your brand\\n- Define programmable transaction behavior at the domain level\\n\\n---\\n\\n### White-label application domain\\n\\nDeploy a fully re-branded application interface under your own domain.\\n\\nThis includes:\\n\\n- Custom frontend styling\\n- Enterprise UX adjustments\\n- Integrated workflows\\n- Institutional-grade onboarding logic\\n\\nCurvy infrastructure operates in the background while your brand remains fully visible.\\n\\n---\\n\\n### Custom fee models\\n\\nDefine pricing and settlement logic aligned with your business model.\\n\\nOptions include:\\n\\n- Ecosystem-level fee configuration\\n- Subsidized privacy flows\\n- Revenue sharing structures\\n\\nYou control how value flows through your ecosystem.\\n\\n---\\n\\n### Custom privacy aggregator routing\\n\\nControl where and how funds are aggregated inside the Privacy Aggregator.\\n\\nThis enables:\\n\\n- Dedicated aggregation pools\\n- Jurisdiction-specific routing\\n- Institutional liquidity separation\\n- Controlled exit pathways\\n\\n---\\n\\n### Custom networks and tokens\\n\\nSupport only the chains and assets relevant to your organization.\\n\\n- Restrict allowed networks\\n- Whitelist approved tokens\\n- Define asset-level risk policies\\n- Align infrastructure with internal mandates\\n\\n---\\n\\n### Custom compliance rules\\n\\nCurvy includes a modular compliance framework that can be aligned with your institutional requirements.\\n\\nConfigurable components include:\\n\\n- KYB / KYC integrations\\n- KYT integrations\\n- Risk scoring thresholds\\n- Sanctions screening\\n- Policy-based transaction filtering\\n- Retroactive compliance models\\n- Viewing key frameworks for full audit capability\\n\\n---\\n\\n### 24/7 Enterprise support\\n\\nEnterprise partners receive:\\n\\n- SLA-backed support\\n- Dedicated communication channel\\n- Technical collaboration workflow\\n- Prioritized roadmap alignment\\n- Security response coordination\\n\\n---\\n\\n## Architecture Overview\\n\\nCurvy provides:\\n\\n- Non-custodial smart contract infrastructure\\n- Stealth address-based private receiving\\n- ZK-based Privacy Aggregator for private execution\\n- Compliance-aware Portal Broadcasters\\n- SDK for system-level integration\\n\\nEnterprises can integrate:\\n\\n- Identity layer only\\n- Privacy receiving only\\n- Full shielding and aggregation flows\\n- Or fully customized infrastructure stack\\n\\n---\\n\\n## Designed for Institutional Use Cases\\n\\nCurvy is suitable for:\\n\\n- Payment processors\\n- Regulated exchanges\\n- Fintech platforms\\n- Enterprise treasury operations\\n- Blockchain ecosystems\\n- Institutional DeFi access layers\\n\\n---\\n\\n## Why Curvy for Enterprise?\\n\\n- Non-custodial by design\\n- Privacy and compliance combined\\n- Fully programmable infrastructure\\n- Brand-level control\\n- Multi-chain deployment\\n- Enterprise-grade support model\\n","rawMarkdownPath":"/_raw/for-businesses/for-enterprises-and-institutions.md","rawMarkdownTitle":"Curvy for Enterprises & Institutions","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-businesses/for-enterprises-and-institutions.md"},"headers":[],"relativePath":"for-businesses/for-enterprises-and-institutions.md","filePath":"for-businesses/for-enterprises-and-institutions.md","lastUpdated":1773768298000}'),a={name:"for-businesses/for-enterprises-and-institutions.md"};function o(s,e,l,u,c,d){return r(),i("div",null,[...e[0]||(e[0]=[t("",56)])])}const m=n(a,[["render",o]]);export{h as __pageData,m as default};
